"""
Builds the compiler of every commit that has a different code state and runs the short benchmark set (benchmarks/history.py --quick) with it.

    python3 benchmarks/history_commits.py --repo PATH --since COMMIT [--until COMMIT] [--limit N]

--repo is a clone with the submodules (it is checked out and built in, so do not use a clone you are working in). A "code state" is the
trees of code_compiler, code_runtime and third_party: commits that only change documentation, tests, CI or the wiki have the same state as the
commit before, and share its result. The result of every state is saved in commits/<commit>.json in the checkout of the performance-history branch, with the commits that
share it; a build that fails is saved with the end of its log. Commits that already have a result are skipped, so it can be stopped and
continued. The commits are taken in the order of `git rev-list --reverse --topo-order`, merge commits included.
"""
import argparse
import json
import os
import shutil
import subprocess
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
RESULTS = os.environ.get("PERF_HISTORY", os.path.join(os.path.dirname(os.path.dirname(HERE)), "performance-history"))
OUT = os.path.join(RESULTS, "commits")


def git(repo, *args, check=True):
    return subprocess.run(["git", "-C", repo] + list(args), capture_output=True, text=True, check=check).stdout.strip()


def code_key(repo, commit):
    r = subprocess.run(["git", "-C", repo, "rev-parse", commit + ":code_compiler", commit + ":code_runtime", commit + ":third_party",
                        commit + ":cmake", commit + ":CMakeLists.txt"], capture_output=True, text=True)
    return tuple(r.stdout.split()) if r.returncode == 0 else (commit,)


def fetch_binary(repo_slug, commit, dest):
    """Downloads the artifacts of the CI runs of a commit with `gh` and gives the folder that has blitzcc (or None). For a machine that can not build."""
    shutil.rmtree(dest, ignore_errors=True)
    os.makedirs(dest)
    runs = subprocess.run(["gh", "run", "list", "-R", repo_slug, "--commit", commit, "--json", "databaseId,conclusion,workflowName", "--limit", "20"],
                          capture_output=True, text=True)
    try:
        ids = [r["databaseId"] for r in json.loads(runs.stdout) if r["conclusion"] == "success"]
    except ValueError:
        ids = []
    for i in ids:
        subprocess.run(["gh", "run", "download", str(i), "-R", repo_slug, "-D", os.path.join(dest, str(i)), "--pattern", "*windows*x64*"], capture_output=True, text=True)
        for root, _, files in os.walk(dest):
            for f in files:
                if f in ("blitzcc", "blitzcc.exe"):
                    return root
    return None


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--repo", required=True)
    parser.add_argument("--since", required=True, help="the first commit (exclusive: its children are taken)")
    parser.add_argument("--until", default="origin/root")
    parser.add_argument("--limit", type=int, default=0)
    parser.add_argument("--max-minutes", type=float, default=0, help="stop after the state that is running when this time is over (chunks)")
    parser.add_argument("--scratch", default=os.path.join(os.path.expanduser("~"), "commit-builds"))
    parser.add_argument("--build-script", metavar="SCRIPT", help="build with this PowerShell script (Windows; benchmarks/build_windows.ps1) instead of build_rev.sh")
    parser.add_argument("--build-dir", default=os.path.join(os.path.expanduser("~"), "commit-build-tree"), help="build folder that is kept between commits")
    parser.add_argument("--download", metavar="OWNER/REPO", help="do not build: download the CI binaries of every commit with gh (Windows)")
    args = parser.parse_args()
    os.makedirs(OUT, exist_ok=True)
    commits = git(args.repo, "rev-list", "--reverse", "--topo-order", args.since + ".." + args.until).split()
    states = []  # (key, [commits])
    index = {}
    for c in commits:
        key = code_key(args.repo, c)
        if key in index:
            states[index[key]][1].append(c)
        else:
            index[key] = len(states)
            states.append((key, [c]))
    print("%d commits, %d code states" % (len(commits), len(states)), flush=True)
    done = 0
    started = time.time()
    for n, (key, group) in enumerate(states):
        first = group[0]
        path = os.path.join(OUT, first + ".json")
        if os.path.isfile(path):
            continue
        if args.max_minutes and time.time() - started > args.max_minutes * 60:
            print("time is over, %d states done" % done, flush=True)
            break
        label = "c%04d-%s" % (n, first[:8])
        scratch = os.path.join(args.scratch, label)
        shutil.rmtree(scratch, ignore_errors=True)
        os.makedirs(scratch)
        record = {"commit": first, "commits": group, "subject": git(args.repo, "log", "-1", "--format=%s", first),
                  "date": git(args.repo, "log", "-1", "--format=%as", first)}
        if args.download:
            built = fetch_binary(args.download, first, os.path.join(scratch, "ci"))
            exe = os.path.join(built or "", "blitzcc.exe")
            build = subprocess.CompletedProcess([], 0 if built else 1, "", "no CI binary for this commit")
        elif args.build_script:
            built = os.path.join(scratch, "install")
            build = subprocess.run(["powershell", "-NoProfile", "-File", args.build_script, "-Repo", args.repo, "-Commit", first, "-Out", built,
                                    "-Build", args.build_dir], capture_output=True, text=True)
            for root, _, files in os.walk(built):
                if "blitzcc.exe" in files:
                    built = root
                    break
            exe = os.path.join(built, "blitzcc.exe")
        else:
            build = subprocess.run(["/home/user/bench/build_rev.sh", first, label], capture_output=True, text=True)
            built = os.path.join("/home/user/revs", label)
            exe = os.path.join(built, "blitzcc")
        if build.returncode != 0 or not os.path.isfile(exe):
            tail = ""
            log = os.path.join(built or "", "build.log")
            if os.path.isfile(log):
                tail = "\n".join(open(log, errors="replace").read().splitlines()[-12:])
            record["build_error"] = (tail or build.stdout + build.stderr)[-1500:]
            print("%s %s build failed" % (label, first[:8]), flush=True)
        else:
            out = os.path.join(scratch, "result.json")
            run = subprocess.run([sys.executable, os.path.join(HERE, "history.py"), "--quick", "--blitzcc", exe,
                                  "--label", label, "--rev", first, "--out", out], capture_output=True, text=True, stdin=subprocess.DEVNULL)
            if os.path.isfile(out):
                record.update(json.load(open(out)))
                record["commit"], record["commits"], record["date"] = first, group, git(args.repo, "log", "-1", "--format=%as", first)
            else:
                record["run_error"] = (run.stdout + run.stderr)[-800:]
            print("%s %s ok" % (label, first[:8]), flush=True)
        json.dump(record, open(path, "w"), indent=1)
        if not args.download and not args.build_script:
            shutil.rmtree(built, ignore_errors=True)
        shutil.rmtree(scratch, ignore_errors=True)
        done += 1
        if args.limit and done >= args.limit:
            break


if __name__ == "__main__":
    main()
